export type Method = "symlink" | "copy";

/**
 *  One row that could not be computed keeps its place in the list with the
 *  reason, so a broken folder never hides the healthy ones.
 */
export type MineListRow = { state: "ready"; row: MineRow } | { state: "unreadable"; path: string; why: string };

/**  One Mine row, computed fresh from the folder on every ask. */
export type MineRow = {
	path: string,
	/**  The catalog's own name, or the folder leaf where it says nothing. */
	name: string,
	description: string | null,
	license: string | null,
	/**  Discovered packages per kind name. */
	counts: { [key in string]: number },
	bundles: number,
	/**
	 *  Whether a control file (`kendex.toml`) declares the layout — the
	 *  offers surface reads this to know what to offer.
	 */
	declared: boolean,
	breakage: number,
	heldBack: number,
	warned: number,
	advisory: number,
	/**  Every check finding, file-first, so the app can open each one. */
	findings: StatusFinding[],
	git: GitReadiness,
};

/**
 *  One item as the scanner found it — read-only truth, no interpretation of
 *  whether it is declared or managed.
 */
export type ObservedItem = {
	kind: ItemKind,
	name: string,
	harness: HarnessId,
	scope: Scope,
	/**  Path of the artifact, or of the config file that contains the entry. */
	path: string,
	fileState: FileState,
	/**
	 *  Observable enabled/disabled state; `None` when the harness has no
	 *  observable toggle for this kind.
	 */
	enabled: boolean | null,
	/**  Best-effort provenance: git origin URL of the content's real location. */
	origin: string | null,
	description: string | null,
	/**
	 *  What this item says it is for. Empty when it says nothing — a tag is
	 *  something an author writes down, never something inferred from a
	 *  name, because a wrong guess is worse than no answer.
	 */
	tags: Tag[],
	/**
	 *  Unix seconds the primary file last changed, as `u32` because specta
	 *  refuses to export a 64-bit int (precision loss crossing the IPC
	 *  boundary) — good until year 2106. `None` where the item has no
	 *  single file of its own to stat (a config-entry kind, or a stat that
	 *  failed) — a shared file's mtime does not describe any one entry
	 *  inside it.
	 */
	modifiedAt: number | null,
	/**
	 *  Who ships this content, when a tool ships it itself — see
	 *  [`crate::vendor`]. `None` is the common case: the user's own.
	 */
	vendor: string | null,
};

/**  One offered write, previewed: the exact relative path and bytes. */
export type OfferPreview = {
	rel: string,
	bytes: string,
};

export type OpSupport = {
	project: boolean,
	global: boolean,
};

/**  Where one installation came from. */
export type Origin = 
/**
 *  Installed from a subscription: its declared alias and its repository
 *  (or path) as the lock recorded them.
 */
{ origin: "marketplace"; source: string; repo: string } | 
/**
 *  The user's own content in the local source — adopted, or forked off
 *  a marketplace item, in which case this names what it replaced.
 */
{ origin: "own"; forkedFrom: string | null } | 
/**  On disk and observed, managed by nothing. */
{ origin: "unmanaged" };

/**  Whether a recorded override still speaks for what is in front of us. */
export type OverrideState = 
/**  Nothing recorded for this installation. */
{ state: "absent" } | 
/**  Recorded, and still describing exactly this. */
{ state: "active" } | 
/**  Recorded, but what it was granted against has changed since. */
{ state: "stale"; why: string };

