/**
 *  The subscription a browsed repository already has on this machine, so
 *  the page can carry on as that subscription instead of a stranger.
 */
export type SubscriptionRef = {
	scope: Scope,
	source: string,
};

/**  The job an item helps with. */
export type Tag = 
/**  Reading code and saying what is wrong with it. */
"review" | 
/**  Writing, running, or reasoning about tests. */
"testing" | 
/**  Documentation, references, and explaining things in prose. */
"docs" | 
/**  Finding things out — sources, prior art, evidence. */
"research" | 
/**  Deciding what to build and in what order. */
"planning" | 
/**  Reshaping code that already works. */
"refactoring" | 
/**  Working out why something is broken. */
"debugging" | 
/**  Safety, secrets, permissions, and untrusted input. */
"security" | 
/**  Speed, memory, and the cost of running something. */
"performance" | 
/**  Version control — branches, history, worktrees, pull requests. */
"git" | 
/**  Compiling, packaging, versioning, and shipping a release. */
"release" | 
/**  Databases, schemas, migrations, and analysis. */
"data" | 
/**  Interfaces: layout, styling, design systems, accessibility. */
"ui" | 
/**  Talking to other services — APIs, webhooks, third-party tools. */
"integration" | 
/**  Driving other tools and agents, and the workflows that chain them. */
"automation";

/**
 *  Where warning starts and where installing stops. Configured in app
 *  settings rather than in a manifest: a manifest travels with the
 *  repository it describes, and a catalog that could lower the bar it is
 *  measured against is not being measured.
 */
export type Thresholds = {
	"warn-below": number,
	"block-below": number,
};

/**
 *  What unsubscribing from a marketplace would do: the packages that can be
 *  removed or kept as-is, the ones the user edited (which must be forked or
 *  discarded first), and the curated sets that leave with the source.
 */
export type UnsubscribePreview = {
	removable: PackageRef[],
	edited: PackageRef[],
	bundles: string[],
};

/**  One declared package's update standing. */
export type UpdateRow = {
	scope: Scope,
	kind: ItemKind,
	name: string,
	source: string,
	repo: string,
	/**
	 *  `repo` as [`crate::source_ref::repo_identity`] spells it — the one
	 *  identity two scopes' rows share when they name one repository two
	 *  ways, on any host.
	 */
	repoIdentity: string,
	/**  The content revision installed now, when the lock records it. */
	current: VersionRef | null,
	/**  The newest content revision the mirror knows. */
	latest: VersionRef | null,
	/**
	 *  The package's files changed between current and latest — a moved
	 *  repository that never touched this package is not an update.
	 */
	updateAvailable: boolean,
	/**
	 *  Held at a version — the effective installation graph's word, not
	 *  only the item's own `rev`: a pinned source, a pinned bundle, or a
	 *  pinned dependency parent all hold what they carry.
	 */
	pinned: boolean,
	/**  Who holds it, when `pinned`. */
	holdOwner: HoldOwner | null,
	/**  The user asked to stop hearing about this package's updates. */
	ignored: boolean,
	/**
	 *  The installed files were edited by hand; updating is blocked until
	 *  the edit is kept as a fork or discarded.
	 */
	blockedByLocalEdit: boolean,
	/**
	 *  Which renderings carry the edit, one entry per physical rendering:
	 *  an agent renders once per tool, while tools sharing a skill's
	 *  canonical tree count once. Keeping the edit as a fork captures one
	 *  rendering's bytes — it has to be the one that was changed.
	 */
	editedHarnesses: HarnessId[],
	/**
	 *  The edited rendering a fork can capture, when one exists — an
	 *  agent edited only in a tool whose format cannot be read back has
	 *  none, and the UI must not offer what the engine will refuse.
	 */
	forkableHarness: HarnessId | null,
	/**
	 *  Whether dropping the edits can put the currently resolved content
	 *  back in place, without moving any revision — the source content
	 *  resolved, whether or not its history could be read. False once the
	 *  source no longer carries the package.
	 */
	canDiscard: boolean,
	/**
	 *  Whether this place can move to the newest content on its own: the
	 *  newest is known, and the hold — if any — is this declaration's to
	 *  move rather than a bundle's or parent's.
	 */
	canTakeLatest: boolean,
	/**
	 *  Installed as a bundle member or a dependency, with no declaration
	 *  of its own: whatever pulled it in owns its revision, and a fork
	 *  needs a declaration to turn local.
	 */
	derived: boolean,
	/**  This package is a local fork of a catalog item. */
	forked: boolean,
	/**  Installations of this package disagree on their source commit. */
	mixed: boolean,
	/**  The source's tracked tip no longer carries this package at all. */
	removedUpstream: boolean,
};

/**
 *  Update standing for one scope, and every package the standing could not
 *  be computed for. The warnings are the report's honesty: a package whose
 *  mirror cannot be read is listed here, never silently shown as current.
 */
export type UpdatesReport = UpdatesReport_Serialize | UpdatesReport_Deserialize;

/**
 *  Update standing for one scope, and every package the standing could not
 *  be computed for. The warnings are the report's honesty: a package whose
 *  mirror cannot be read is listed here, never silently shown as current.
 */
export type UpdatesReport_Deserialize = {
	rows: UpdateRow[],
	warnings: ItemWarning_Deserialize[],
};

/**
 *  Update standing for one scope, and every package the standing could not
 *  be computed for. The warnings are the report's honesty: a package whose
 *  mirror cannot be read is listed here, never silently shown as current.
 */
export type UpdatesReport_Serialize = {
	rows: UpdateRow[],
	warnings: ItemWarning_Serialize[],
};

export type Verdict = 
/**  Nothing found worth saying. */
"clean" | 
/**  Findings worth reading before installing; the install proceeds. */
"warn" | 
/**  Nothing installs until a person reviews it. */
"block";

/**  One version a row points at. */
export type VersionRef = {
	commit: string,
	/**  Release name when a tag points at the commit. */
	label: string | null,
	date: string | null,
};

/**
 *  One version of a package: a commit that changed its files, wearing any
 *  tag names that point at it.
 */
export type VersionRow = {
	/**  Full commit id. */
	id: string,
	/**  The release name, when a tag points at this commit. */
	label: string | null,
	/**  ISO-8601 committer date. */
	date: string,
	summary: string,
	/**  This is the content revision the installed package holds. */
	installed: boolean,
	newerThanInstalled: boolean,
};

/**  One side of the comparison. */
export type VersionSel = 
/**  The package's source subtree at a commit. */
{ at: "commit"; commit: string } | 
/**  What is installed on disk right now. */
{ at: "installed" };

export type ZoomState = {
	/**
	 *  The size on screen. Every resize the window takes moves it, so a
	 *  page that has just reloaded reads what it is looking at.
	 */
	percent: number,
	/**
	 *  The window would not take the saved size when it opened, so
	 *  `percent` is the fallback and the saved size is not on screen. A
	 *  fact about the opening: a resize that works later moves the size but
	 *  does not make the opening have worked.
	 */
	launchRefused: boolean,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

